 112: /// One step of the commit sequence, in order. The variants before [`WriteStep::TakeWriteLock`]
 113: /// happen without the lock; the rest happen while it is held; releasing is implicit at the
 114: /// end. This is the documented, machine-checkable encoding of the write order.
 115: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
 116: pub enum WriteStep {
 117:     /// `.reply.json` - the byte-for-byte raw copy, before anything parses it.
 118:     RawReply,
 119:     /// Take `.consult.write.lock` (backoff up to 60 s) and mark the record `committing`.
 120:     TakeWriteLock,
 121:     /// Re-read `findings.json` and `sessions.json` under the lock.
 122:     ReReadStores,
 123:     /// The rendered handoff `.md`.
 124:     HandoffMarkdown,
 125:     /// `findings.json` (this run's delta applied to the fresh store).
 126:     Findings,
 127:     /// `sessions.json` - the entry inserted by `n`; THE commit point.
 128:     Sessions,
 129:     /// Remove (or keep, marked `committing`) the recovery record.
 130:     RemoveRecoveryRecord,
 131:     /// Close the write-lock handle.
 132:     ReleaseWriteLock,
 133: }
