 405: fn leading_number(name: &str) -> Option<u32> {
 406:     let digits: String = name.chars().take_while(|c| c.is_ascii_digit()).collect();
 407:     if digits.len() >= 2 && name[digits.len()..].starts_with('-') {
 408:         digits.parse().ok()
 409:     } else {
 410:         None
 411:     }
 412: }
