 49: /// Format a parsed [`Value`] as the PowerShell-5.1 text (no trailing newline). Used by the
 50: /// formatter's own tests to prove byte-identity independently of any typed struct.
 51: pub fn format_value_root(value: &Value) -> String {
 52:     let mut out = String::new();
 53:     write_value(&mut out, value, 0);
 54:     out
 55: }
 56: 
 57: fn write_value(out: &mut String, value: &Value, col: usize) {
 58:     match value {
 59:         Value::Object(map) => {
 60:             if map.is_empty() {
 61:                 out.push_str("{\n\n");
 62:                 push_spaces(out, col);
 63:                 out.push('}');
 64:                 return;
 65:             }
 66:             out.push_str("{\n");
 67:             let last = map.len() - 1;
 68:             let child_indent = col + 4;
 69:             for (i, (k, v)) in map.iter().enumerate() {
 70:                 push_spaces(out, child_indent);
 71:                 let key_token = escape_json_string(k);
 72:                 out.push_str(&key_token);
 73:                 out.push_str(":  ");
 74:                 // The value's opening bracket lands here; it drives the value's own indent.
 75:                 let value_col = child_indent + key_token.len() + 3;
 76:                 write_value(out, v, value_col);
 77:                 if i != last {
 78:                     out.push(',');
 79:                 }
 80:                 out.push('\n');
 81:             }
 82:             push_spaces(out, col);
 83:             out.push('}');
 84:         }
 85:         Value::Array(arr) => {
 86:             if arr.is_empty() {
 87:                 // PowerShell 5.1 renders @() as `[`, a blank line, then `]`.
 88:                 out.push_str("[\n\n");
 89:                 push_spaces(out, col);
 90:                 out.push(']');
 91:                 return;
 92:             }
 93:             out.push_str("[\n");
 94:             let last = arr.len() - 1;
 95:             let child_indent = col + 4;
 96:             for (i, v) in arr.iter().enumerate() {
 97:                 push_spaces(out, child_indent);
 98:                 write_value(out, v, child_indent);
 99:                 if i != last {
100:                     out.push(',');
101:                 }
102:                 out.push('\n');
103:             }
104:             push_spaces(out, col);
105:             out.push(']');
106:         }
107:         Value::String(s) => out.push_str(&escape_json_string(s)),
108:         Value::Number(n) => out.push_str(&format_number(n)),
109:         Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
110:         Value::Null => out.push_str("null"),
111:     }
112: }
113: 
114: fn push_spaces(out: &mut String, n: usize) {
115:     for _ in 0..n {
116:         out.push(' ');
117:     }
118: }
