120: /// .NET/JavaScriptSerializer number text: a whole-valued double drops its `.0`.
121: fn format_number(n: &serde_json::Number) -> String {
122:     if let Some(i) = n.as_i64() {
123:         i.to_string()
124:     } else if let Some(u) = n.as_u64() {
125:         u.to_string()
126:     } else {
127:         let f = n.as_f64().unwrap_or(0.0);
128:         if f.is_finite() && f.fract() == 0.0 && f.abs() < 9.007_199_254_740_992e15 {
129:             (f as i64).to_string()
130:         } else {
131:             // Rust's shortest round-trip form: 243.4 -> "243.4".
132:             format!("{f}")
133:         }
134:     }
135: }
