 20: /// Report the first differing byte offset with a little context, for a readable failure.
 21: fn assert_bytes_eq(got: &[u8], want: &[u8], what: &str) {
 22:     if got == want {
 23:         return;
 24:     }
 25:     let n = got.len().min(want.len());
 26:     let mut at = n;
 27:     for i in 0..n {
 28:         if got[i] != want[i] {
 29:             at = i;
 30:             break;
 31:         }
 32:     }
 33:     let lo = at.saturating_sub(60);
 34:     let g = String::from_utf8_lossy(&got[lo..(at + 60).min(got.len())]);
 35:     let w = String::from_utf8_lossy(&want[lo..(at + 60).min(want.len())]);
 36:     panic!(
 37:         "{what}: bytes differ at offset {at} (got {} bytes, want {} bytes)\n  got : {:?}\n  want: {:?}",
 38:         got.len(),
 39:         want.len(),
 40:         g,
 41:         w
 42:     );
 43: }
